}));

function getAirportGroupDescription(code) {
  const descriptions = {
    'AAH': 'American Airlines - Major Hubs',
    'ANZ': 'Australia & New Zealand - Large Airports',
    'ASA': 'Asia - Large Airports',
    'AUL': 'Australia - Large Airports',
